            if (($retval = ProveedorPeer::doValidate($this, $columns)) !== true) {
                $failureMap = array_merge($failureMap, $retval);
            }


                if ($this->collFacturas !== null) {
                    foreach ($this->collFacturas as $referrerFK) {
